def execute(code,run=True):
 s=lib.luaL_newstate();lib.luaL_openlibs(s);raw=code.encode();result=lib.luaL_loadbufferx(s,raw,len(raw),b'pack-test',None)
 if not result and run:result=lib.lua_pcallk(s,0,0,0,0,None)
 message=lib.lua_tolstring(s,-1,None).decode() if result else None
 lib.lua_close(s)
 if message:raise AssertionError(message)
